const { readFileSync } = await import('node:fs');
const mod = await import('html3pdf');
const html2pdf = mod.default || mod;
const htmlString = readFileSync(globalThis.htmlPath, 'utf8');
const worker = html2pdf();
const pdfBase64 = await worker.from(htmlString).toPdf().outputPdf('datauristring');
globalThis.pdfBase64 = pdfBase64;
